// Quick lookup helpers
export const getComponentByName = (name) => {
    return components.find(c => c.name.toLowerCase() === name.toLowerCase());
};
export const getComponentsByCategory = (category) => {
    return components.filter(c => c.category === category);
};
export const searchComponents = (query) => {
    const lowerQuery = query.toLowerCase();
    return components.filter(c => c.name.toLowerCase().includes(lowerQuery) ||
        c.description.toLowerCase().includes(lowerQuery) ||
        c.features.some(f => f.toLowerCase().includes(lowerQuery)) ||
        c.category.toLowerCase().includes(lowerQuery));
};
